import json

STRUCTURED_SCHEMA = [("id", int), ("name", str), ("price", float)]

def validate_structured(row):
    for field, expected_type in STRUCTURED_SCHEMA:
        if field not in row or not isinstance(row[field], expected_type):
            return False
    return True

structured_row = {"id": 1, "name": "Widget", "price": 9.99}
print("structured row valid:", validate_structured(structured_row))

customer_docs = [
    json.loads('{"first_name": "Joe", "emails": ["joe@example.com"]}'),
    json.loads(
        '{"first_name": "Ada", "emails": '
        '["ada@example.com", "ada.work@example.com"], "phone": "555-0100"}'
    ),
]

def describe_document(doc):
    fields = sorted(doc.keys())
    return f"fields={fields} email_count={len(doc.get('emails', []))}"

for doc in customer_docs:
    print(describe_document(doc))
